"""Enumerate candidate intermediate flats G (closed line sets, rank 3..5) of E8 with the design incidences:
cells inside G (design planes P subset G) and sections fed (design planes Q with G subset Q-perp).  Cache to flats.pkl."""
import pickle, os
from common import *
def closure(m): return e8.closure(m)[0]
# all flats of rank 3..5 generated by design planes + lines: generate by closure of unions of 2 planes / plane + line
seen = set()
P_all = planes
for i, A in enumerate(P_all):
    for B in P_all[i:]:
        F = closure(A | B)
        seen.add(F)
    for s in range(V):
        seen.add(closure(A | (1 << s)))
out = []
for F in seen:
    r = e8.dim(F)
    if r < 3 or r > 5: continue
    Fp = perpmask(F)
    cells = [P for P in planes if P & ~F == 0]
    secs = [Q for Q in planes if Q & ~Fp == 0]
    if cells and secs: out.append((F, r, cells, secs))
print('candidate flats', len(out), collections.Counter((r, pc(F)) for F, r, c, s in out).most_common(20))
pickle.dump(out, open('flats.pkl', 'wb'))
